package com.library.dao; import com.library.model.Book; import com.library.util.DBConnection; import java.sql.*; import java.util.*;
public class BookDAO { private Book map(ResultSet r)throws SQLException{Book b=new Book();b.setId(r.getInt("id"));b.setTitle(r.getString("title"));b.setAuthor(r.getString("author"));b.setCategory(r.getString("category"));b.setIsbn(r.getString("isbn"));b.setQuantity(r.getInt("quantity"));b.setAvailableQuantity(r.getInt("available_quantity"));return b;} public List<Book> search(String q)throws SQLException{List<Book>a=new ArrayList<>();String s="SELECT * FROM books WHERE title LIKE ? OR author LIKE ?";try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(s)){String x="%"+(q==null?"":q)+"%";p.setString(1,x);p.setString(2,x);try(ResultSet r=p.executeQuery()){while(r.next())a.add(map(r));}}return a;} }
